/**
 * Wraps text into lines of at most `width` characters.
 * 
 * @param {string} text - The input text to wrap.
 * @param {number} width - The maximum width of each line.
 * @returns {string[]} - An array of wrapped lines.
 */
export function wrapText(text, width) {
  if (width <= 0) return [text];

  const words = text.split(' ');
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If a single word is longer than the width, we must force-break it
    // or include it as is depending on interpretation. 
    // Standard word-wrap usually treats long words as their own line.
    if (currentLength + currentLine.length + word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // If the word itself is wider than the width, we add it to its own line
      if (word.length > width) {
        lines.push(word);
      } else {
        currentLine.push(word);
        currentLength = word.length;
      }
    } else {
      currentLine.push(word);
      currentLength += word.length;
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
