```javascript
/**
 * Turns text into a lowercase, URL-safe slug.
 * 
 * @param {string} text - The input string to slugify.
 * @param {Object} [options] - Optional configuration.
 * @param {number} [options.maxLength] - Maximum length of the resulting slug.
 * @returns {string} - The slugified string.
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') return '';

  let slug = text
    .toString()
    .toLowerCase()
    .trim()
    // Replace spaces with hyphens
    .replace(/\s+/g, '-')
    // Remove all non-word chars (except hyphens)
    .replace(/[^\w\-]+/g, '')
    // Replace multiple hyphens with a single one
    .replace(/\-\-+/g, '-')
    // Remove leading and trailing hyphens
    .replace(/^-+/, '')
    .replace(/-+$/, '');

  if (options.maxLength && typeof options.maxLength === 'number') {
    slug = slug.substring(0, options.maxLength);
    // Ensure we don't end on a dangling hyphen after truncation
    slug = slug.replace(/-+$/, '');
  }

  return slug;
}
