/**
 * Deep equality check for plain data.
 * 
 * @param {unknown} a
 * @param {unknown} b
 * @returns {boolean}
 */
export function deepEqual(a, b) {
  // 1. Strict equality check (handles primitives and same references)
  if (a === b) {
    return true;
  }

  // 2. Handle null and non-object types (if not equal, they are different)
  if (
    a === null ||
    b === null ||
    typeof a !== 'object' ||
    typeof b !== 'object'
  ) {
    return false;
  }

  // 3. Handle Arrays
  if (Array.isArray(a) !== Array.isArray(b)) {
    return false;
  }

  // 4. Handle Objects (including Arrays)
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) {
    return false;
  }

  for (const key of keysA) {
    // Check if key exists in b and recursively compare values
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}
