/**
 * Deep equality check for plain data.
 * Returns true if two values are deeply equal, false otherwise.
 * 
 * @param {unknown} a
 * @param {unknown} b
 * @returns {boolean}
 */
export function deepEqual(a, b) {
  // Check for strict equality (covers primitives and same object references)
  if (a === b) {
    return true;
  }

  // If either is not an object or is null, they are not equal (since a !== b)
  if (
    typeof a !== 'object' || a === null ||
    typeof b !== 'object' || b === null
  ) {
    return false;
  }

  // Check if they are the same type of object (Array vs Object)
  if (Array.isArray(a) !== Array.isArray(b)) {
    return false;
  }

  // Get keys of both objects
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  // Check if they have the same number of keys
  if (keysA.length !== keysB.length) {
    return false;
  }

  // Check if all keys in A exist in B and have the same value
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key)) {
      return false;
    }
    if (!deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}
