/**
 * Formats a byte count into a human-readable string.
 * 
 * @param {number} bytes - The number of bytes to format.
 * @param {Object} [options] - Configuration options.
 * @param {boolean} [options.binary=false] - If true, uses base 1024 (KiB, MiB) instead of base 1000 (kB, MB).
 * @param {number} [options.decimals=2] - Number of decimal places to include.
 * @returns {string} The formatted byte string.
 */
export function formatBytes(bytes, options = {}) {
  const { binary = false, decimals = 2 } = options;

  if (bytes === 0) return '0 B';

  const k = binary ? 1024 : 1000;
  const dm = decimals < 0 ? 0 : decimals;
  const sizes = binary
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB', 'ZiB', 'YiB']
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];

  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return (
    parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i]
  );
}
