/**
 * Parses a URL query string into an object.
 * Handles multiple values for the same key by returning an array.
 * 
 * @param {string} query - The query string (e.g., "?a=1&b=2&a=3")
 * @returns {Record<string, string | string[]>}
 */
export function parseQuery(query) {
  const result = {};

  // Remove the leading '?' if present
  const queryString = query.startsWith('?') ? query.slice(1) : query;

  if (!queryString) {
    return result;
  }

  const pairs = queryString.split('&');

  for (const pair of pairs) {
    if (!pair) continue;

    const [key, value] = pair.split('=').map(decodeURIComponent);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      // If key exists, convert to array if it isn't one already
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value || '');
    } else {
      // Otherwise, set the value
      result[key] = value || '';
    }
  }

  return result;
}
