```javascript
/**
 * Parses a single line of CSV data.
 * Handles quoted fields, escaped quotes (""), and commas within quotes.
 * 
 * @param {string} line - The CSV line to parse.
 * @returns {string[]} - An array of fields.
 */
export function parseCsvLine(line) {
  const fields = [];
  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          // Escaped quote
          currentField += '"';
          i++;
        } else {
          // End of quoted field
          inQuotes = false;
        }
      } else {
        currentField += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        fields.push(currentField);
        currentField = '';
      } else {
        currentField += char;
      }
    }
  }

  fields.push(currentField);
  return fields;
}
