/**
 * Splits an array into smaller arrays of a specified size.
 * 
 * @param {T[]} items - The array to chunk.
 * @param {number} size - The size of each chunk.
 * @returns {T[][]} A new array containing the chunks.
 */
export function chunk(items, size) {
  if (size <= 0) return [];
  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Flattens an array up to a specified depth.
 * 
 * @param {unknown[]} items - The array to flatten.
 * @param {number} [depth=1] - The depth level specifying how deep a nested array structure should be flattened.
 * @returns {unknown[]} A new flattened array.
 */
export function flatten(items, depth = 1) {
  if (depth <= 0) {
    return [...items];
  }

  return items.reduce((acc, item) => {
    if (Array.isArray(item) && depth > 0) {
      acc.push(...flatten(item, depth - 1));
    } else {
      acc.push(item);
    }
    return acc;
  }, []);
}
