export class TokenBucket {
  /**
   * @param {number} capacity - Maximum number of tokens the bucket can hold.
   * @param {number} refillPerSecond - How many tokens are added per second.
   * @param {number} [startTimeMs=0] - Initial time reference.
   */
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.tokens = capacity;
    this.lastRefillMs = startTimeMs;
  }

  /**
   * Internal helper to update the token count based on elapsed time.
   * @param {number} nowMs 
   */
  _refill(nowMs) {
    const elapsedMs = Math.max(0, nowMs - this.lastRefillMs);
    const tokensToAdd = (elapsedMs * this.refillPerSecond) / 1000;

    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefillMs = nowMs;
  }

  /**
   * Attempts to consume a number of tokens.
   * @param {number} count 
   * @param {number} nowMs 
   * @returns {boolean}
   */
  tryTake(count, nowMs) {
    this._refill(nowMs);

    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }

  /**
   * Returns the current number of available tokens.
   * @param {number} nowMs 
   * @returns {number}
   */
  available(nowMs) {
    this._refill(nowMs);
    return this.tokens;
  }
}
