/**
 * Parses a duration string into milliseconds.
 * Supported units:
 * - d: days
 * - h: hours
 * - m: minutes
 * - s: seconds
 * - ms: milliseconds
 * 
 * @param {string} input - The duration string (e.g., "1h30m")
 * @returns {number} The total duration in milliseconds
 */
export function parseDuration(input) {
  if (!input || typeof input !== 'string') return 0;

  const units = {
    d: 86400000,
    h: 3600000,
    m: 60000,
    s: 1000,
    ms: 1
  };

  // Regex to match numbers followed by units
  // Matches groups like "1h", "30m", "500ms"
  const regex = /(\d+(?:\.\d+)?)(d|h|m|s|ms)/g;
  let totalMs = 0;
  let match;
  let found = false;

  while ((match = regex.exec(input)) !== null) {
    const value = parseFloat(match[1]);
    const unit = match[2];

    if (units.hasOwnProperty(unit)) {
      totalMs += value * units[unit];
      found = true;
    }
  }

  return found ? totalMs : 0;
}
