/**
 * A Least-Recently-Used (LRU) cache implementation.
 * Uses a Map to store entries. Since ES6 Map maintains insertion order,
 * we can leverage this to track usage: deleting and re-inserting an entry
 * moves it to the "most recently used" position (the end of the map).
 */
export class LruCache {
  /**
   * @param {number} capacity
   */
  constructor(capacity) {
    if (capacity <= 0) {
      throw new Error("Capacity must be a positive integer.");
    }
    this.capacity = capacity;
    this.cache = new Map();
  }

  /**
   * @param {unknown} key
   * @returns {unknown}
   */
  get(key) {
    if (!this.cache.has(key)) {
      return undefined;
    }
    // Refresh position: delete and re-set to mark as most recently used
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  /**
   * @param {unknown} key
   * @param {unknown} value
   * @returns {this}
   */
  set(key, value) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Map.keys().next().value returns the first (least recently used) key
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    this.cache.set(key, value);
    return this;
  }

  /**
   * @param {unknown} key
   * @returns {boolean}
   */
  has(key) {
    return this.cache.has(key);
  }

  /**
   * @param {unknown} key
   * @returns {boolean}
   */
  delete(key) {
    return this.cache.delete(key);
  }

  /**
   * @returns {number}
   */
  get size() {
    return this.cache.size;
  }

  /**
   * @returns {unknown[]}
   */
  keys() {
    return Array.from(this.cache.keys());
  }
}
