   * Calculates the current number of tokens based on the provided time.
   * @param {number} nowMs 
   * @returns {number}
   */
  available(nowMs) {
    const elapsedMs = Math.max(0, nowMs - this.lastRefillMs);
    const addedTokens = elapsedMs * this.refillRatePerMs;
    return Math.min(this.capacity, this.tokens + addedTokens);
  }

  /**
   * Attempts to consume a number of tokens.
   * @param {number} count 
   * @param {number} nowMs 
   * @returns {boolean} - True if tokens were consumed, false otherwise.
   */
  tryTake(count, nowMs) {
    const currentTokens = this.available(nowMs);

    if (currentTokens < count) {
