 * 
 * @template T
 * @param {T[]} items - The array of items to group.
 * @param {string | ((item: T, index: number) => unknown)} key - The property name or selector function.
 * @returns {Map<unknown, T[]>} A Map where keys are the grouping values and values are arrays of items.
 */
export function groupBy(items, key) {
  const map = new Map();
  const isFunction = typeof key === 'function';

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const groupKey = isFunction ? key(item, i) : item[key];

    if (!map.has(groupKey)) {
