/**
 * Wraps text to a specified width.
 * 
 * @param {string} text - The text to wrap.
 * @param {number} width - The maximum width of each line.
 * @returns {string[]} - An array of wrapped lines.
 */
export function wrapText(text, width) {
  if (width <= 0) return [text];

  const words = text.split(' ');
  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If a single word is longer than the width, we must force-break it
    // or include it as is. Based on standard requirements, we treat it as a line.
    if (word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      lines.push(word);
      continue;
    }

    // Check if adding the word exceeds the width
    // (currentLength + word.length + space)
    if (currentLength + word.length + (currentLine.length > 0 ? 1 : 0) <= width) {
      currentLine.push(word);
      currentLength += word.length + (currentLine.length > 1 ? 1 : 0);
    } else {
      lines.push(currentLine.join(' '));
      currentLine = [word];
      currentLength = word.length;
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
