/**
 * A token-bucket rate limiter that relies on an external clock.
 */
export class TokenBucket {
  /**
   * @param {number} capacity - The maximum number of tokens the bucket can hold.
   * @param {number} refillPerSecond - How many tokens are added per second.
   * @param {number} [startTimeMs=0] - The initial timestamp for the bucket.
   */
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    this.capacity = capacity;
    this.refillRate = refillPerSecond / 1000; // tokens per millisecond
    this.tokens = capacity;
    this.lastRefillTime = startTimeMs;
  }

  /**
   * Calculates the current number of tokens available at a given time.
   * @param {number} nowMs - The current time in milliseconds.
   * @returns {number}
   */
  available(nowMs) {
    if (nowMs <= this.lastRefillTime) {
      return this.tokens;
    }

    const elapsed = nowMs - this.lastRefillTime;
    const added = elapsed * this.refillRate;
    return Math.min(this.capacity, this.tokens + added);
  }

  /**
   * Attempts to consume a number of tokens.
   * @param {number} count - Number of tokens to take.
   * @param {number} nowMs - The current time in milliseconds.
   * @returns {boolean} - True if tokens were taken, false otherwise.
   */
  tryTake(count, nowMs) {
    const currentTokens = this.available(nowMs);

    if (currentTokens < count) {
      return false;
    }

    this.tokens = currentTokens - count;
    this.lastRefillTime = nowMs;
    return true;
  }
}
