/**
 * Turns text into a lowercase, URL-safe slug.
 * 
 * @param {string} text - The input string to slugify.
 * @param {object} [options] - Configuration options.
 * @param {number} [options.maxLength] - Optional maximum length of the slug.
 * @returns {string} The slugified string.
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    return '';
  }

  let slug = text
    .toString()
    .normalize('NFD') // Split accented characters into base char + diacritic
    .replace(/[\u0300-\u036f]/g, '') // Remove diacritics
    .toLowerCase()
    .replace(/[^a-z0-9 -]/g, '') // Remove non-alphanumeric characters (except space and hyphen)
    .replace(/\s+/g, '-') // Replace spaces with hyphens
    .replace(/-+/g, '-') // Replace multiple hyphens with a single one
    .replace(/^-+/, '') // Trim hyphens from start
    .replace(/-+$/, ''); // Trim hyphens from end

  if (options.maxLength && typeof options.maxLength === 'number') {
    slug = slug.substring(0, options.maxLength);
    // Ensure we don't end on a dangling hyphen after truncation
    slug = slug.replace(/-+$/, '');
  }

  return slug;
}
