/**
 * Parses a single line of CSV data.
 * Handles fields enclosed in double quotes and escaped double quotes ("").
 * 
 * @param {string} line - The CSV line to parse.
 * @returns {string[]} - An array of fields.
 */
export function parseCsvLine(line) {
  const result = [];
  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        // Check for escaped quote (double double-quote)
        if (line[i + 1] === '"') {
          currentField += '"';
          i++;
        } else {
          // End of quoted field
          inQuotes = false;
        }
      } else {
        currentField += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        // End of field
        result.push(currentField);
        currentField = '';
      } else {
        currentField += char;
      }
    }
  }

  // Push the final field
  result.push(currentField);

  return result;
}
