export class TokenBucket {
  /**
   * @param {number} capacity - Maximum number of tokens the bucket can hold.
   * @param {number} refillPerSecond - Number of tokens added per second.
   * @param {number} [startTimeMs] - Initial time in milliseconds.
   */
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    this.capacity = capacity;
    this.refillRatePerMs = refillPerSecond / 1000;
    this.tokens = capacity;
    this.lastRefillMs = startTimeMs;
  }

  /**
   * Calculates the current number of tokens available.
   * @param {number} nowMs - Current time in milliseconds.
   * @returns {number}
   */
  available(nowMs) {
    const elapsedMs = Math.max(0, nowMs - this.lastRefillMs);
    const refill = elapsedMs * this.refillRatePerMs;
    return Math.min(this.capacity, this.tokens + refill);
  }

  /**
   * Attempts to take a specified number of tokens.
   * @param {number} count - Number of tokens to take.
   * @param {number} nowMs - Current time in milliseconds.
   * @returns {boolean} - True if tokens were taken, false otherwise.
   */
  tryTake(count, nowMs) {
    const currentTokens = this.available(nowMs);

    if (currentTokens < count) {
      return false;
    }

    this.tokens = currentTokens - count;
    this.lastRefillMs = nowMs;
    return true;
  }
}
